var DATA = {"record_type": "invoice record", "target": "PDF renderer program", "mapping": "id => Invoice #|lines => Line items|total => Total due", "example": "{\"id\": \"INV-1\", \"lines\": 3, \"total\": \"99.99\"}"};
console.log("Linkage: " + DATA.record_type + " -> " + DATA.target);
var rec = JSON.parse(DATA.example);
console.log("Source record: " + JSON.stringify(rec));
var lines = ["// generated from " + DATA.record_type, "// target: " + DATA.target, "function run(record) {"];
DATA.mapping.split("|").forEach(function (m) {
  var parts = m.split("=>").map(function (s) { return s.trim(); });
  if (parts.length === 2) lines.push('  console.log("' + parts[1] + ': " + record["' + parts[0] + '"]);');
});
lines.push("}", "run(" + JSON.stringify(rec) + ");");
var program = lines.join("\n");
console.log("--- generated program ---");
console.log(program);
console.log("--- program output ---");
eval(program);
console.log("RESULT: program generated from record and executed.");

